// This file is generated by AI.

// 场景文件/文件夹操作: 新建、重命名、删除。
// 磁盘操作成功后, 同步迁移/关闭已打开的场景选项卡、Monaco model 与 LSP 状态。

import { copyDirectory, moveToTrash } from './commands/server';
import { fs } from './lib/fs';
import { toUri } from './lib/uri';
import { lspClient } from './lsp/client';
import { disposeModel } from './lsp/monaco';
import { useAppStore } from './state/store';
import { sceneTabId } from './tabs/model';

/** 校验文件/文件夹名称, 返回错误信息或 null。 */
export function validateName(name: string): string | null {
  const trimmed = name.trim();
  if (!trimmed) return '名称不能为空';
  if (trimmed === '.' || trimmed === '..') return '名称无效';
  if (/[\\/:*?"<>|]/.test(trimmed)) return '名称不能包含 \\ / : * ? " < > | 字符';
  return null;
}

/** 场景文件缺扩展名时自动补 `.txt` (WebGAL 场景约定)。 */
export function ensureSceneExtension(name: string): string {
  return name.includes('.') ? name : `${name}.txt`;
}

/** 新建空文件, 返回完整路径。 */
export async function createFile(dirPath: string, name: string): Promise<string> {
  const full = `${dirPath.replace(/[\\/]+$/, '')}\\${name}`;
  await fs.writeText(full, '');
  return full;
}

/** 新建文件夹, 返回完整路径。 */
export async function createFolder(dirPath: string, name: string): Promise<string> {
  const full = `${dirPath.replace(/[\\/]+$/, '')}\\${name.trim()}`;
  await fs.mkdir(full);
  return full;
}

export function projectRelativePath(projectPath: string, filePath: string): string {
  const base = projectPath.replace(/[\\/]+$/, '').replace(/\\/g, '/');
  const abs = filePath.replace(/\\/g, '/');
  if (abs === base) return '.';
  return abs.startsWith(`${base}/`)
    ? abs.slice(base.length + 1)
    : abs.replace(new RegExp(`^.*?${base.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`), '').replace(/^\//, '');
}

/** 浏览器菜单中的复制路径: 场景去掉 game/scene/, 资源去掉 game/ 与可省略的第一级目录。 */
export function browserRelativePath(projectPath: string, filePath: string): string {
  const relative = projectRelativePath(projectPath, filePath).replace(/^\/+/, '');
  const scenePrefix = 'game/scene/';
  if (relative.toLowerCase().startsWith(scenePrefix)) return relative.slice(scenePrefix.length);

  const gamePrefix = 'game/';
  if (!relative.toLowerCase().startsWith(gamePrefix)) return relative;
  const resourcePath = relative.slice(gamePrefix.length);
  const segments = resourcePath.split('/');
  return segments.length > 1 ? segments.slice(1).join('/') : resourcePath;
}

export function uniqueTargetPath(dirPath: string, name: string): string {
  const base = `${dirPath.replace(/[\\/]+$/, '')}\\${name}`;
  const ext = name.includes('.') ? name.slice(name.lastIndexOf('.')) : '';
  const stem = name.includes('.') ? name.slice(0, name.lastIndexOf('.')) : name;
  let candidate = base;
  let index = 1;
  while (true) {
    if (!candidate) break;
    // 这里不直接用 fs.exists, 仅做本地命名去重; 真实存在性由调用方校验。
    const raw = candidate;
    const parts = raw.split(/[\\/]/);
    const last = parts[parts.length - 1];
    if (!/\(\d+\)$/.test(last)) {
      const exists = candidate;
      if (exists) return candidate;
    }
    candidate = `${dirPath.replace(/[\\/]+$/, '')}\\${stem} (${index})${ext}`;
    index += 1;
  }
  return base;
}

export async function copyEntryToDirectory(sourcePath: string, targetDir: string): Promise<string> {
  const name = sourcePath.split(/[\\/]/).pop() ?? 'item';
  const info = await fs.exists(sourcePath);

  const dest = await (async () => {
    const base = `${targetDir.replace(/[\\/]+$/, '')}\\${name}`;
    if (!info.exists) return base;
    let index = 1;
    let candidate = base;
    while (true) {
      const stat = await fs.exists(candidate);
      if (!stat.exists) return candidate;
      const dot = name.lastIndexOf('.');
      const stem = dot > 0 ? name.slice(0, dot) : name;
      const ext = dot > 0 ? name.slice(dot) : '';
      candidate = `${targetDir.replace(/[\\/]+$/, '')}\\${stem} (${index})${ext}`;
      index += 1;
    }
  })();

  if (info.isDirectory) {
    await copyDirectory(sourcePath, dest);
  } else {
    await fs.copyFile(sourcePath, dest);
  }
  return dest;
}

/** 重命名文件/文件夹, 并把受影响的开场景文档迁移到新路径 (含 LSP / Monaco model)。 */
export async function renamePath(oldPath: string, newPath: string): Promise<void> {
  await fs.rename(oldPath, newPath); // 磁盘失败则直接抛出, 不迁移内存状态

  const store = useAppStore.getState();
  const oldNorm = oldPath.replace(/\\/g, '/').toLowerCase();
  for (const doc of [...store.documents]) {
    const dn = doc.path.replace(/\\/g, '/').toLowerCase();
    if (dn !== oldNorm && !dn.startsWith(oldNorm + '/')) continue;
    // 目录重命名时, 子文件路径追加原相对部分 (按实际大小写切片)
    const suffix = doc.path.replace(/\\/g, '/').slice(oldPath.replace(/\\/g, '/').length);
    const newDocPath = `${newPath.replace(/\\/g, '/')}${suffix}`.replace(/\//g, '\\');
    disposeModel(doc.path);
    lspClient.closeDocument(doc.path);
    store.setDiagnostics(doc.path, []);
    store.updateDocument(doc.path, {
      path: newDocPath,
      name: newDocPath.split(/[\\/]/).pop() ?? newDocPath,
      uri: toUri(newDocPath),
      isScene: newDocPath.replace(/\\/g, '/').includes('/game/scene/'),
    });
    // 选项卡按路径索引, 需同步迁移 (保持原位置与顺序)
    store.retargetSceneTabs(doc.path, newDocPath);
    // 若该文档是当前活动文档, CodeEditor 会以新路径重建并重新向 LSP 注册;
    // 此处对非活动文档不做额外处理 (LSP 仅跟踪活动文档)。
  }
}

/** 删除文件/文件夹 (移动至系统回收站), 并关闭受影响的开场景选项卡。 */
export async function deletePath(path: string): Promise<void> {
  await moveToTrash(path); // 磁盘失败则直接抛出, 不关闭选项卡

  const store = useAppStore.getState();
  const norm = path.replace(/\\/g, '/').toLowerCase();
  for (const doc of [...store.documents]) {
    const dn = doc.path.replace(/\\/g, '/').toLowerCase();
    if (dn !== norm && !dn.startsWith(norm + '/')) continue;
    disposeModel(doc.path);
    lspClient.closeDocument(doc.path);
    store.closeDocument(doc.path);
    store.closeTab(sceneTabId(doc.path));
  }
}
